var i=`0508-jerusalem-mixed-grill`;var t=`world-0508`;var o=`IL`;var a=`western-asia`;var r=4;var s=24;var l={en:`Jerusalem Mixed Grill`,ua:`Єрусалимський мікс-гриль`};var d={en:`A traditional dish from Israel, centered on chicken liver, chicken hearts, yellow onion, chicken breast. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ізраїль. Основні складники: куряча печінка, курячі серця, жовта цибуля, куряча грудка. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`chicken-liver`,250,`g`],[`chicken-hearts`,220,`g`],[`yellow-onion`,250,`g`],[`sunflower-oil`,40,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 10 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 10 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:10,i:[[`chicken-breast`,270,`g`],[`ground-cumin`,5,`g`],[`ground-turmeric`,3,`g`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`pita-bread`,4,`pcs`],[`parsley`,25,`g`]]}];var g={slug:i,id:t,country:`IL`,region:a,servings:4,minutes:24,title:l,text:d,steps:u};export{o as country,g as default,t as id,s as minutes,a as region,r as servings,i as slug,u as steps,d as text,l as title};